// Offline policy monitor. Trust only a table generated by a verified compiler.
// An application must authenticate its observations and gate the real action.
const own=(obj,key)=>Object.hasOwn(obj,key);
export class PolicySession {
  #table; #state; #failed=false;
  constructor(table, initialObservation, expectedModelHash) {
    if (table.format!==1 || table.model_sha256!==expectedModelHash || !own(table.initial,initialObservation)) throw Error('policy binding or initial observation mismatch');
    this.#table=structuredClone(table); this.#state=this.#table.initial[initialObservation];
    if (!own(this.#table.nodes,this.#state)) throw Error('invalid policy node');
  }
  allowed() {return this.#failed?[]:Object.keys(this.#table.nodes[this.#state].actions).sort();}
  get done(){return !this.#failed && this.#table.nodes[this.#state].rank===0;}
  step(action, observation) {
    if (!this.allowed().includes(action)) throw Error('action denied');
    const next=this.#table.nodes[this.#state].actions[action];
    if (!own(next,observation) || !own(this.#table.nodes,next[observation]) || this.#table.nodes[next[observation]].rank>=this.#table.nodes[this.#state].rank) {this.#failed=true; throw Error('unexpected observation; session invalidated');}
    this.#state=next[observation];
  }
}
